   auto enter=[&](const QString &value){events();for(auto *scroll:panel->findChildren<QScrollArea *>())if(scroll->isAncestorOf(input))scroll->ensureWidgetVisible(input);events();require(input->isVisible()&&input->isEnabled()&&!input->isReadOnly(),"VF13ad iteration control not visible");input->setFocus();input->selectAll();QTest::keyClicks(input,value);events();require(input->text()==value&&table->item(row,1)->text()==value,"VF13ad visible input lost typed value or backing property");acceptanceView(*child);};
   const int originalIterations=opt->GetIntegerParameter(opt->GetParameterID("MaximumIterations"));enter("-1");QTest::mouseClick(panel->findChild<QDialogButtonBox *>("resourceButtons")->button(QDialogButtonBox::Apply),Qt::LeftButton);events();require(rig.source->toPlainText()==created&&Moderator::Instance()->GetConfiguredObject("Opt")->GetIntegerParameter("MaximumIterations")==originalIterations,"Invalid VF13ad iterations changed source/native value");
   enter("70");QTest::mouseClick(panel->findChild<QDialogButtonBox *>("resourceButtons")->button(QDialogButtonBox::Apply),Qt::LeftButton);events();require(Moderator::Instance()->GetConfiguredObject("Opt")->GetIntegerParameter("MaximumIterations")==70,"VF13ad iteration GUI Apply lost native value");const auto applied=rig.source->toPlainText();require(applied!=created,"VF13ad iteration GUI Apply missing source edit");rig.closePanels();rig.source->undo();require(rig.source->toPlainText()==created&&rig.window.buildScript(),"VF13ad resource Undo not exact");rig.source->redo();require(rig.source->toPlainText()==applied&&rig.window.buildScript(),"VF13ad resource Redo not exact");rig.save("created-applied.script",applied.toUtf8());
   const auto boundary=applied.indexOf("BeginMissionSequence;");require(boundary>0,"VF13ad resource mission boundary missing");Options options;const auto numerical=applied.left(boundary)+rig.configuration(70)+rig.body(options);rig.source->setPlainText(numerical);rig.run("gui-resource",options);const auto saved=rig.files.filePath("VF13ad resource Ω.script");require(rig.window.saveScriptTo(saved)&&rig.window.loadScript(saved)&&rig.source->toPlainText()==numerical,"VF13ad resource Unicode reopen changed source");rig.run("reopened",options);rig.source->setPlainText(rig.script(options,70));rig.run("script",options);
   const QJsonObject proof{{"checkpoint","vf13ad-resource-create"},{"outcome","passed"},{"family","vf13ad-resource"},{"create_dialogs",2},{"invalid_iteration_rejections",1},{"phases",3},{"facets",QJsonArray{"actual-solvers-category-vf13ad-create-cancel-and-native-type","actual-mdi-property-input-invalid-correction-and-history","live-vf13ad-analytic-constrained-result-and-raw-reports","unicode-reopen-and-independent-script-route"}},{"scope","Bundled VF13ad live optimizer created through actual native Qt category/creator and configured MaximumIterations through actual visible property input. One invalid correction, exact source/history/reopen and scalar constrained quadratic result; not every optimizer property/problem, default-client/native OS input/platform/hardware/stress/science or current NASA/full-suite qualification."}};rig.save("proof.json",QJsonDocument(proof).toJson());std::cout<<"NASA_CHECK "<<QJsonDocument(proof).toJson(QJsonDocument::Compact).constData()<<std::endl;return 0;
